  function orderingToggleChecks(button){var card=button&&button.closest?button.closest('.card'):null,panel=card&&card.querySelector('.ord-check-panel');if(!panel)return;var open=panel.hidden;panel.hidden=!open;button.setAttribute('aria-expanded',open?'true':'false');button.classList.toggle('open',open);if(open){var first=panel.querySelector('button');if(first){first.focus({preventScroll:true});/* C33 : la vérification dépliée doit être visible, pas seulement focalisée. */try{first.scrollIntoView({block:'nearest',behavior:'smooth'});}catch(e){}}}}
  function activateGroup(g,row){if(!g)return;if(g.site&&g.site!==w.DB.site&&typeof w.setSite==='function')w.setSite(g.site);if(row&&row.space&&row.space!==w.DB.space&&typeof w.setSpace==='function')w.setSpace(row.space);}
