  function orderingResolveCheck(key,code){var g=findGroup(key);if(!g)return;if(code==='delivery-after-need'&&needForGroup(g)){orderingEditNeed(needForGroup(g).id);return;}if(code==='supplier-missing'){activateGroup(g);openSupplier('');return;}if(/^(schedule-unknown|schedule-unverified|cutoff-missed|minimum-not-met)$/.test(code)){activateGroup(g);openSupplier(g.supplier);return;}openProductForGroup(g);}
