    if(!retour){var all=po.lines.every(function(l){return n(l.receivedQty,3)+n(l.refusedQty||0,3)>=n(l.quantity,3)-.0001;}),some=po.lines.some(function(l){return n(l.receivedQty,3)>0;});po.status=all?'received':(some?'partial':po.status);po.receiptControl='completed';po.receiptControlledAt=at;if(!po.receivedAt)po.receivedAt=at;po.lastReceivedAt=at;}
