  function historicLines(po){var lines=['COMMANDE — '+po.supplier,'Établissement : '+siteTitle(po.site),'Statut : '+statusLabel(po.status),'Créée le : '+new Date(po.createdAt).toLocaleString('fr-FR'),''];po.lines.forEach(function(l){lines.push('• ['+zoneTitle(l.space)+'] '+l.name+(l.sku?' — réf. '+l.sku:'')+' : '+qty(l.quantity)+' '+l.unit+' — reçu '+qty(l.receivedQty||0)+' — refusé '+qty(l.refusedQty||0)+' — retourné '+qty(l.returnedQty||0));});lines.push('', 'SUIVI DES ECARTS', 'Responsable déclaré : '+(po.declaredBy||'non renseigné'));po.lines.forEach(function(l){lines.push('',l.name);lines=lines.concat(lineAudit(l));lines.push(anticipation(l));});lines.push('Suppléments estimés, pas des pertes. Retours : '+(po.returns||[]).length+' événement(s).');return lines;}
