  function openSupplierManager(){var names=supplierNames(w.DB.site),cal=calendarFor(w.DB.site);document.getElementById('supplierManagerList').innerHTML='<button class="ord-calendar-card" onclick="openEstablishmentCalendar()"><b>Calendrier de l’établissement</b><span>'+cal.seasons.length+' saison'+(cal.seasons.length>1?'s':'')+' · '+cal.exceptions.length+' exception'+(cal.exceptions.length>1?'s':'')+' · modifier ouvertures, fermetures et services</span></button>'+(names.length?names.map(function(name){var p=ensureProfile(w.DB.site,name),next=O.nextWindows(p,new Date(),35,{calendar:cal})[0];return '<div class="ord-supplier-row"><div><b>'+e(name)+'</b><span>'+(p.rules.length?(p.rules.length+' passage'+(p.rules.length>1?'s':'')+' · '+(next?'prochaine limite '+O.formatDateTime(next.cutoffAt):'aucun passage possible avec le calendrier')):'aucun horaire renseigné')+' · '+(p.verified?'confirmé':'à confirmer')+'</span></div><button data-sup="'+e(name)+'" onclick="openSupplier(this.dataset.sup)">Modifier</button></div>';}).join(''):'<div class="ord-note">Aucun fournisseur. Ajoutez d’abord un produit ou créez un fournisseur.</div>');document.getElementById('mSuppliers').classList.add('on');}
