  function weekEditor(target,prefix,week){var box=document.getElementById(target);if(!box)return;week=normalizeWeek(week);box.innerHTML=week.map(function(d,i){return '<div class="ord-week-row"><b>'+e(O.days[i])+'</b><select id="'+prefix+'State'+i+'" onchange="calendarDayToggle(\''+prefix+'\','+i+')"><option value="open"'+(d.state==='open'?' selected':'')+'>Ouvert</option><option value="closed"'+(d.state==='closed'?' selected':'')+'>Fermé au public</option><option value="no-access"'+(d.state==='no-access'?' selected':'')+'>Fermé sans accès</option></select><input id="'+prefix+'Open'+i+'" type="time" value="'+e(d.openAt)+'" aria-label="Ouverture '+e(O.days[i])+'"><input id="'+prefix+'Close'+i+'" type="time" value="'+e(d.closeAt)+'" aria-label="Fermeture '+e(O.days[i])+'"><input id="'+prefix+'Services'+i+'" type="number" min="1" max="6" value="'+d.services+'" aria-label="Services '+e(O.days[i])+'"></div>';}).join('');for(var i=0;i<7;i++)calendarDayToggle(prefix,i);}
  function calendarDayToggle(prefix,i){var open=document.getElementById(prefix+'State'+i).value==='open';['Open','Close','Services'].forEach(function(k){document.getElementById(prefix+k+i).disabled=!open;});}
  function collectWeek(prefix){var out=[];for(var i=0;i<7;i++){var state=document.getElementById(prefix+'State'+i).value;out.push({state:state,openAt:document.getElementById(prefix+'Open'+i).value,closeAt:document.getElementById(prefix+'Close'+i).value,services:state==='open'?Math.max(1,Math.min(6,Math.round(Number(document.getElementById(prefix+'Services'+i).value)||2))):0});}return out;}
  function calendarPreset(kind){if(kind==='custom'){CAL_EDIT.week=collectWeek('cal');drawCalendarPreview();return;}var week=defaultWeek();if(kind==='sun'||kind==='sunmon')week[0].state='closed';if(kind==='sunmon')week[1].state='closed';CAL_EDIT.week=normalizeWeek(week);weekEditor('calWeek','cal',CAL_EDIT.week);drawCalendarPreview();}
  function easterSunday(y){var a=y%19,b=Math.floor(y/100),c=y%100,d=Math.floor(b/4),f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*(b%4)+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=(h+l-7*m+114)%31+1;return new Date(y,month-1,day,12);}
  function holidaySuggestions(){var out=[],now=new Date(),limit=O.addDays(now,550);[now.getFullYear(),now.getFullYear()+1].forEach(function(y){var easter=easterSunday(y),fixed=[['01-01','Jour de l’An'],['05-01','Fête du Travail'],['05-08','Victoire 1945'],['07-14','Fête nationale'],['08-15','Assomption'],['11-01','Toussaint'],['11-11','Armistice'],['12-25','Noël']];fixed.forEach(function(x){out.push({date:y+'-'+x[0],label:x[1]});});[[1,'Lundi de Pâques'],[39,'Ascension'],[50,'Lundi de Pentecôte']].forEach(function(x){out.push({date:O.dateKey(O.addDays(easter,x[0])),label:x[1]});});});return out.filter(function(x){var d=O.localDate(x.date);return d>=new Date(now.getFullYear(),now.getMonth(),now.getDate())&&d<=limit;}).sort(function(a,b){return a.date.localeCompare(b.date);}).slice(0,12);}
  function drawHolidaySuggestions(){var box=document.getElementById('calHolidays');if(!box)return;box.innerHTML=holidaySuggestions().map(function(x){var exists=CAL_EDIT.exceptions.some(function(a){return a.date===x.date;});return '<button type="button"'+(exists?' disabled':'')+' data-date="'+e(x.date)+'" data-label="'+e(x.label)+'" onclick="addHolidayException(this.dataset.date,this.dataset.label)"><b>'+e(new Date(x.date+'T12:00:00').toLocaleDateString('fr-FR'))+'</b><span>'+e(x.label)+(exists?' · déjà décidé':' · proposer comme fermeture')+'</span></button>';}).join('');}
  function addHolidayException(date,label){if(CAL_EDIT.exceptions.some(function(x){return x.date===date;}))return;CAL_EDIT.exceptions.push({id:id('exc'),date:date,state:'closed',openAt:'',closeAt:'',services:0,note:label+' · fermeture confirmée manuellement'});drawCalendarLists();}
  function drawCalendarLists(){var s=document.getElementById('calSeasons'),x=document.getElementById('calExceptions');if(s)s.innerHTML=CAL_EDIT.seasons.length?CAL_EDIT.seasons.map(function(a,i){return '<div class="ord-rule-row"><div><b>'+e(a.label||'Saison')+'</b><span>'+e(a.from||'début à préciser')+' → '+e(a.to||'fin à préciser')+'</span></div><button data-i="'+i+'" onclick="openSeason(Number(this.dataset.i))">Modifier</button></div>';}).join(''):'<p class="sub">Aucune saison : la semaine habituelle s’applique toute l’année.</p>';if(x)x.innerHTML=CAL_EDIT.exceptions.length?CAL_EDIT.exceptions.slice().sort(function(a,b){return a.date.localeCompare(b.date);}).map(function(a,i){var original=CAL_EDIT.exceptions.indexOf(a),label={open:'Ouverture',closed:'Fermeture', 'no-access':'Fermeture sans accès'}[a.state];return '<div class="ord-rule-row"><div><b>'+e(new Date(a.date+'T12:00:00').toLocaleDateString('fr-FR'))+' · '+e(label)+'</b><span>'+e(a.note||'Exception datée prioritaire')+'</span></div><button data-i="'+original+'" onclick="openCalendarException(Number(this.dataset.i))">Modifier</button></div>';}).join(''):'<p class="sub">Aucune exception datée.</p>';drawHolidaySuggestions();drawCalendarPreview();}
  function drawCalendarPreview(){var box=document.getElementById('calPreview');if(!box)return;var rows=[];for(var i=0;i<14;i++){var d=O.addDays(new Date(),i),v=O.calendarDay(CAL_EDIT,d);rows.push('<span class="ord-cal-day '+e(v.state)+'"><b>'+e(O.days[d.getDay()]+' '+String(d.getDate()).padStart(2,'0'))+'</b><small>'+(v.state==='open'?v.services+' service'+(v.services>1?'s':''):(v.state==='no-access'?'sans accès':'fermé'))+(v.source!=='habituel'?' · '+e(v.source):'')+'</small></span>');}box.innerHTML=rows.join('');}
  function openEstablishmentCalendar(){document.getElementById('mSuppliers').classList.remove('on');CAL_EDIT=normalizeCalendar(clone(calendarFor(w.DB.site)));weekEditor('calWeek','cal',CAL_EDIT.week);drawCalendarLists();document.getElementById('mCalendar').classList.add('on');}
