  function saveSeason(){var from=document.getElementById('seasonFrom').value,to=document.getElementById('seasonTo').value;if(!from||!to||from>to){w.toast('Indiquez une période saisonnière valide');return;}var s={id:SEASON_IDX>=0?CAL_EDIT.seasons[SEASON_IDX].id:id('sea'),label:text(document.getElementById('seasonLabel').value,80)||'Saison',from:from,to:to,week:collectWeek('season')};if(SEASON_IDX>=0)CAL_EDIT.seasons[SEASON_IDX]=s;else CAL_EDIT.seasons.push(s);document.getElementById('mSeason').classList.remove('on');drawCalendarLists();}
