  function openRule(index){RULE_IDX=Number.isFinite(index)?index:-1;var r=RULE_IDX>=0?SUP_EDIT.rules[RULE_IDX]:normalizeRule({orderDay:5,cutoff:'11:50',deliveryDay:6,deliveryStart:'04:00',deliveryEnd:'06:00',active:true});document.getElementById('ruleTitle').textContent=RULE_IDX>=0?'Modifier le passage':'Ajouter un passage';document.getElementById('ruleLabel').value=r.label||'';document.getElementById('ruleOrderDay').innerHTML=dayOptions(r.orderDay);document.getElementById('ruleCutoff').value=r.cutoff||'';document.getElementById('ruleDeliveryDay').innerHTML=dayOptions(r.deliveryDay);document.getElementById('ruleStart').value=r.deliveryStart||'';document.getElementById('ruleEnd').value=r.deliveryEnd||'';document.getElementById('ruleFrom').value=r.validFrom||'';document.getElementById('ruleTo').value=r.validTo||'';document.getElementById('ruleActive').checked=r.active!==false;document.getElementById('ruleDelete').style.display=RULE_IDX>=0?'block':'none';document.getElementById('mRule').classList.add('on');}
